window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-14f1536cb869d450"]={"versions": [{"id": "FIG-14f1536cb869d450", "releases": ["R1.3.0", "R17-03_R1.1.0", "R17-10_R1.2.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Struktur- und Datenflussdiagramm im Kontext des AUTOSAR Remote Event Communication Protocols (RECM). Das Diagramm visualisiert die grundlegende PDU-Struktur einer Mode $04 Notification Management Message sowie deren Übertragungsrichtung zwischen zwei Steuergeräten über ein Fahrzeug-Bussystem.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zwei übergeordnete Steuergeräte-Instanzen (ECUs) agieren als Kommunikationsendpunkte:</p>\n<ul class=\"fig-list\"><li><strong>Destination Section ECU</strong>: Sendende Steuereinheit, die Benachrichtigungs-Management-Nachrichten generiert und über den Bus aussendet.\n</li><li><strong>Source Section ECU</strong>: Empfangende Steuereinheit, die die Nachricht aufnimmt.\n</li></ul>\n<p class=\"fig-p\">Die übertragene Nachricht wird als dreidimensional dargestellter Datenblock (PDU-Array) mit drei sequenziellen Feldern abgebildet:</p>\n<ul class=\"fig-list\"><li><strong>MSG_TYPE</strong>: Erstes Feld des Nachrichten-Headers zur Kennzeichnung des Nachrichtentyps.\n</li><li><strong>RESERVED</strong>: Mittleres Feld, reserviert für zukünftige Protokollerweiterungen.\n</li><li><strong>MSG_CTR</strong>: Abschließendes Feld zur Zählung bzw. Sequenzierung der Nachrichten.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Kommunikationsablauf verläuft unidirektional:</p>\n<ol class=\"fig-list\"><li>Die <strong>Destination Section ECU</strong> generiert eine Mode $4 Notification Management Message. Ein nach unten weisender Pfeil signalisiert die Bereitstellung bzw. das Senden der PDU auf den Kommunikationskanal.\n</li><li>Die PDU durchläuft die Übertragung mit ihrer dreigliedrigen Feldstruktur (<code>MSG_TYPE</code>, <code>RESERVED</code>, <code>MSG_CTR</code>).\n</li><li>Ein geschwungener, nach oben gerichteter Pfeil führt von der PDU zur <strong>Source Section ECU</strong>, die die Nachricht empfängt, validiert und verarbeitet.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert die logische Anordnung und Übertragungsrichtung der Mode 4 Notification Management PDU gemäß RECM-Spezifikation. Für Implementierer ist zu beachten:</p>\n<ul class=\"fig-list\"><li>Die Flussrichtung erfolgt explizit von der Destination Section ECU zur Source Section ECU (Rückmelde- bzw. Benachrichtigungspfad).\n</li><li>Die serielle Abfolge der Felder (<code>MSG_TYPE</code> gefolgt von <code>RESERVED</code> und <code>MSG_CTR</code>) ist strikt einzuhalten.\n</li><li>Das Feld <code>RESERVED</code> muss bei der Protokoll-Serialisierung und -Deserialisierung exakt gemäß Bytegröße und Padding-Vorgaben der Spezifikation reserviert und verarbeitet werden.\n</li><li><code>MSG_CTR</code> dient der Überwachung von Nachrichtenverlust, Reihenfolge und Duplikaten auf Empfängerseite.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-6de6f8b5b252e194", "releases": ["R18-03_R1.4.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Struktur- und Datenflussdiagramm im Kontext des AUTOSAR Remote Event Communication Protocols (RECM). Das Diagramm visualisiert die grundlegende PDU-Struktur einer Mode $04 Notification Management Message sowie deren Übertragungsrichtung zwischen zwei Steuergeräten über ein Fahrzeug-Bussystem.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zwei übergeordnete Steuergeräte-Instanzen (ECUs) agieren als Kommunikationsendpunkte:</p>\n<ul class=\"fig-list\"><li><strong>Destination Section ECU</strong>: Sendende Steuereinheit, die Benachrichtigungs-Management-Nachrichten generiert und über den Bus aussendet.\n</li><li><strong>Source Section ECU</strong>: Empfangende Steuereinheit, die die Nachricht aufnimmt.\n</li></ul>\n<p class=\"fig-p\">Die übertragene Nachricht wird als dreidimensional dargestellter Datenblock (PDU-Array) mit drei sequenziellen Feldern abgebildet:</p>\n<ul class=\"fig-list\"><li><strong>MSG_TYPE</strong>: Erstes Feld des Nachrichten-Headers zur Kennzeichnung des Nachrichtentyps.\n</li><li><strong>RESERVED</strong>: Mittleres Feld, reserviert für zukünftige Protokollerweiterungen.\n</li><li><strong>MSG_CTR</strong>: Abschließendes Feld zur Zählung bzw. Sequenzierung der Nachrichten.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Kommunikationsablauf verläuft unidirektional:</p>\n<ol class=\"fig-list\"><li>Die <strong>Destination Section ECU</strong> generiert eine Mode $4 Notification Management Message. Ein nach unten weisender Pfeil signalisiert die Bereitstellung bzw. das Senden der PDU auf den Kommunikationskanal.\n</li><li>Die PDU durchläuft die Übertragung mit ihrer dreigliedrigen Feldstruktur (<code>MSG_TYPE</code>, <code>RESERVED</code>, <code>MSG_CTR</code>).\n</li><li>Ein geschwungener, nach oben gerichteter Pfeil führt von der PDU zur <strong>Source Section ECU</strong>, die die Nachricht empfängt, validiert und verarbeitet.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert die logische Anordnung und Übertragungsrichtung der Mode 4 Notification Management PDU gemäß RECM-Spezifikation. Für Implementierer ist zu beachten:</p>\n<ul class=\"fig-list\"><li>Die Flussrichtung erfolgt explizit von der Destination Section ECU zur Source Section ECU (Rückmelde- bzw. Benachrichtigungspfad).\n</li><li>Die serielle Abfolge der Felder (<code>MSG_TYPE</code> gefolgt von <code>RESERVED</code> und <code>MSG_CTR</code>) ist strikt einzuhalten.\n</li><li>Das Feld <code>RESERVED</code> muss bei der Protokoll-Serialisierung und -Deserialisierung exakt gemäß Bytegröße und Padding-Vorgaben der Spezifikation reserviert und verarbeitet werden.\n</li><li><code>MSG_CTR</code> dient der Überwachung von Nachrichtenverlust, Reihenfolge und Duplikaten auf Empfängerseite.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-14f1536cb869d450", "to": "FIG-6de6f8b5b252e194", "fr": "R17-10_R1.2.0", "tr": "R18-03_R1.4.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
